const response = items[0].json.text || items[0].json.response || '{}';
try {
  items[0].json.social_content = JSON.parse(response.replace(/```json\n?|```/g, '').trim());
} catch (e) {
  items[0].json.social_content = {
    platform: items[0].json.platform || 'twitter',
    content: 'Could not generate content',
    hashtags: [],
    image_suggestion: '',
    best_time: 'Morning',
    engagement_hook: ''
  };
}
return items;

parameters.jsonBody:
={
  "documentId": "unique()",
  "data": {
    "content_type": "{{ $json.social_content.platform }}_post",
    "title": "{{ $json.topic || 'Social Post' }}",
    "ai_draft": "{{ $json.social_content.content }}",
    "status": "draft",
    "agent_source": "CMO Agent",
    "created_at": "{{ new Date().toISOString() }}",
    "updated_at": "{{ new Date().toISOString() }}"
  }
}

parameters.jsCode:
return [{
  json: {
    success: true,
    ...items[0].json.social_content,
    requires_approval: true,
    message: `${items[0].json.social_content?.platform} post drafted for review`
  }
}];
